def problem(x: np.ndarray) -> float:
    dim = len(x)
    z = (x + 5) / 10  # Scale and shift to [0, 1]
    return float(np.sum(z**2) + 0.1 * np.cos(2 * np.pi * z[0]) + 0.05 * z[1]**3)

