import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (
        0.115 * (x1**3 + x2**3 + x3**3)/300   # Skewness
        + 0.571 * (x1 + 2*x2 - x3) / 10       # Linearity, Variance
        + 0.911 * np.abs(x1) /10             # Nearest-better Connectivity
        + 0.654 * (x1**2 + x2**2 + x3**2)/300  # Simple Quadratic
        + np.sin(x1 + x2 + x3) / 20               # Add non-linearity
    )

