import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (
        0.115 * (x1**3 + x2**3 - x3**2) / 300  # Skewness from cubic and quadratic.
        + 0.571 * (2*x1 - x2 + x3) / 10           # Linearity, adjust variance
        + 0.911 * np.abs(x2-x3) / 10             # Nearest-better connectivity based on difference
        + 0.654 * (x1**2 - x2**2 + x3) / 300       # Simple quadratic, add linear term
        + np.cos(x1 * x2 - x3) / 20              # Add non-linearity based input interactions
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (
        0.115 * (x1 + x2 + x3) / 10      # Linearity & skew
        + 0.571 * np.abs(x1 - x2) / 10   # Absolute difference
        + 0.911 * np.sin(x1 + x2 + x3)/10  # Sinusoidal component
        + 0.654 * (x1 + x2) / 20         #Linear term for NBC control.
        + 0.1 * x3
    )

