import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    w = np.array([1.0, 0.5, 0.25])[:dim] # Dimension-dependent scaling

    cosine_term = np.sum(np.cos(w * x[:dim]))

    cross_product_term = 1.0
    for i in range(dim):
      cross_product_term *= x[i]

    linear_term = np.sum(w * x[:dim])

    return float(0.1 * cosine_term + 0.005 * cross_product_term + 0.05 * linear_term)

import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    w = np.array([0.5, 0.2, 0.1])[:dim]
    s = np.sum(w * x[:dim])
    return float(s + np.prod(np.sqrt(np.abs(x[:dim] - 1))) + (s**3 - s**2 + s))

import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    w = np.array([0.5, 0.3, 0.2])[:dim]
    weighted_sum = np.sum(w * x[:dim]) / dim

    exp_term = 0.0
    if dim > 1:
        for i in range(dim - 1):
            exp_term += (x[i] - x[i+1])**2
        exp_term = 0.05 * np.exp(-0.1 * exp_term)
    else:
        exp_term = 0.05 * np.exp(-0.1 * x[0]**2)

    sum_coords = np.sum(x[:dim])
    polynomial_term = 0.01 * (sum_coords**2 - 2 * sum_coords + 1) / dim

    return float(weighted_sum + exp_term + polynomial_term)

import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    w = np.array([0.7, 0.2, 0.1])[:dim]
    linear_part = np.sum(w * x[:dim])

    abs_diff_sum = np.sum(np.abs(x[:-1] - x[1:])) if dim > 1 else 0.0
    sqrt_product = 0.1 * np.sqrt(abs_diff_sum + 1e-8)

    scaled_sum = np.sum((x[:dim] + 5)/10)
    polynomial = 0.01 * scaled_sum**2

    sine_wave = 0.05 * np.sin(2 * np.pi * scaled_sum)

    log_barrier = 0.0
    for i in range(dim):
        if x[i] <= -5 or x[i] >= 5:
           return float('inf')
        log_barrier += -0.01 * np.log(25 - x[i]**2)

    return float(linear_part + sqrt_product + polynomial + sine_wave + log_barrier)

import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    w = np.array([0.7, 0.2, 0.1])[:dim]
    linear_part = np.sum(w * x[:dim])

    sqrt_product = 0.0
    if dim > 1:
        sqrt_product = 0.1
        for i in range(dim - 1):
            sqrt_product *= np.sqrt(np.abs(x[i] - x[i+1]))

    scaled_sum = np.sum((x[:dim] + 5)/10)
    polynomial = 0.01 * scaled_sum**4

    return float(linear_part + sqrt_product + polynomial)

