import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    w = np.array([0.7, 0.2, 0.1])[:dim]
    linear_part = np.sum(w * x[:dim])

    squared_diff_product = 1.0
    if dim > 1:
        for i in range(dim - 1):
            squared_diff_product *= (x[i] - x[i+1])**2

    scaled_sum = np.sum((x[:dim] + 5) / 10)
    polynomial = 0.01 * ((scaled_sum - 0.5)**5 - 2*(scaled_sum-0.5)**3 + (scaled_sum-0.5))

    sinusoidal_term = 0.05 * np.sin(10 * scaled_sum)

    return float(linear_part + 0.001*squared_diff_product + polynomial + sinusoidal_term)
